exports.handler = async (event, context) => {
  const log = (kind, extra = {}) => console.log('SQSTHR ' + JSON.stringify({kind, at: Date.now(), requestId: context.awsRequestId, ...extra}));
  log('start', {event});
  if (event.holdMs) {
    await new Promise(resolve => setTimeout(resolve, event.holdMs));
    log('hold_complete', {token: event.token});
    return {ok: true, token: event.token};
  }
  for (const record of event.Records || []) {
    const body = JSON.parse(record.body);
    if (body.mode === 'error_once' && Number(record.attributes.ApproximateReceiveCount) === 1) {
      log('throw', {messageId: record.messageId, receiveCount: record.attributes.ApproximateReceiveCount});
      throw new Error('owned deliberate function-code failure on first receive');
    }
  }
  log('success', {messageIds: (event.Records || []).map(record => record.messageId)});
  return {ok: true};
};

